// Keep in sync with ALLOWED_SENDERS in .streamlit/secrets.toml (the API checks again).
const ALLOWED = ['REPLACE_WITH_YOUR_SENDER_EMAIL'];
const KEEP = /\.(xlsx|pdf|jpe?g|png)$/i;
const IMAGE = /\.(jpe?g|png)$/i;
const MIN_IMAGE_BYTES = 20 * 1024; // Smaller pictures are email signature logos: skipped, no alert.
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const from = item.json.from;
  const raw = typeof from === 'string' ? from : ((from && from.value && from.value[0] && from.value[0].address) || (from && from.text) || '');
  const match = raw.match(/<([^>]+)>/);
  const address = (match ? match[1] : raw).trim().toLowerCase();
  if (!ALLOWED.includes(address)) continue; // Other senders stop here: no API call, no alert.
  for (const [key, file] of Object.entries(item.binary || {})) {
    const name = file.fileName || '';
    if (!KEEP.test(name)) continue;
    if (IMAGE.test(name)) {
      const bytes = await this.helpers.getBinaryDataBuffer(i, key);
      if (bytes.length < MIN_IMAGE_BYTES) continue;
    }
    out.push({ json: { sender: address, subject: item.json.subject || '', fileName: name }, binary: { data: file } });
  }
}
return out;
